SELECT

FROM UserRebate a WHERE 1 = 1

    AND a.inviterId = #{inviterId}


    AND a.inviteeId = #{inviteeId}


    AND a.tradeId = #{tradeId}


    AND a.tradeAmount = #{tradeAmount}


    AND a.feeAmount = #{feeAmount}


    AND a.rebateRate = #{rebateRate}


    AND a.rebateAmount = #{rebateAmount}


    AND a.status = #{status}


    AND a.settleDate = #{settleDate}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}

limit 1

SELECT

FROM UserRebate a WHERE 1 = 1

    AND a.inviterId = #{inviterId}


    AND a.inviteeId = #{inviteeId}


    AND a.tradeId = #{tradeId}


    AND a.tradeAmount = #{tradeAmount}


    AND a.feeAmount = #{feeAmount}


    AND a.rebateRate = #{rebateRate}


    AND a.rebateAmount = #{rebateAmount}


    AND a.status LIKE CONCAT('%',#{status}, '%')


    AND a.settleDate = #{settleDate}


    AND a.createTime = #{createTime}


    AND a.updateTime = #{updateTime}
